SELECT id, revenue, NTILE(3) OVER (PARTITION BY product_id ORDER BY revenue DESC, id) revenue_bucket, ROUND(revenue / SUM(revenue) OVER (PARTITION BY YEAR(sale_date), store_id), 4) revenue_share, CUME_DIST() OVER (PARTITION BY product_id, store_id ORDER BY revenue NULLS LAST) revenue_cume_dist, LAST_VALUE(revenue) IGNORE NULLS OVER (PARTITION BY store_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_revenue FROM store_sales
